import React from 'react';
import { motion } from 'framer-motion';
import {
  IconDashboard,
  IconTasks,
  IconProfile,
  IconPomodoro,
  IconBook,
} from '../assets/icons';
import { useNavigate, useLocation } from 'react-router-dom';

// Variants for dock animations
const dockVariants = {
  hidden: { y: 100, opacity: 0 },
  visible: { 
    y: 0, 
    opacity: 1,
    transition: { 
      type: "spring", 
      stiffness: 300, 
      damping: 30,
      staggerChildren: 0.05
    }
  }
};

const iconVariants = {
  hidden: { y: 20, opacity: 0 },
  visible: { 
    y: 0, 
    opacity: 1,
    transition: { type: "spring", stiffness: 300, damping: 20 }
  }
};

// Neural network connection line between icons
const NeuralConnector = ({ startX, endX, isActive }) => (
  <svg 
    className="absolute top-1/2 h-0.5 pointer-events-none" 
    style={{ 
      left: `${startX}px`, 
      width: `${endX - startX}px`,
      transform: 'translateY(-50%)',
      zIndex: 0
    }}
  >
    <line 
      x1="0" 
      y1="1" 
      x2="100%" 
      y2="1" 
      stroke={isActive ? "rgba(100, 200, 255, 0.6)" : "rgba(100, 200, 255, 0.1)"} 
      strokeWidth="1"
      strokeDasharray={isActive ? "none" : "3,3"}
    />
    
    {isActive && (
      <motion.circle 
        r="3"
        fill="#80CFFF"
        initial={{ cx: 0, opacity: 0 }}
        animate={{ 
          cx: ['0%', '100%'],
          opacity: [0, 1, 0]
        }}
        transition={{ 
          duration: 1.5, 
          repeat: Infinity,
          ease: "easeInOut" 
        }}
      />
    )}
  </svg>
);

// Memoized DockIcon for performance
const DockIcon = React.memo(({ icon: Icon, label, onClick, isActive, to }) => {
  // Use a simple callback that just calls the parent's onClick with the path
  const handleClick = () => {
    onClick(to);
  };

  return (
    <motion.div
      className="flex flex-col items-center justify-center cursor-pointer touch-manipulation"
      whileHover={{ 
        scale: 1.05,
        y: -3,
        transition: { 
          type: "spring", 
          stiffness: 500, 
          damping: 15
        } 
      }}
      whileTap={{ 
        scale: 0.95,
        transition: { duration: 0.1 } 
      }}
      onClick={handleClick}
      role="button"
      aria-label={`Navigate to ${label}`}
      aria-pressed={isActive}
      tabIndex={0}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          handleClick();
        }
      }}
      variants={iconVariants}
    >
      <motion.div 
        className={`p-2 rounded-xl ${
          isActive 
            ? 'bg-gradient-to-b from-neural-300/90 to-neural-600/90 text-white shadow-lg shadow-neural-500/20 neural-glow backdrop-blur-md' 
            : 'bg-gray-900/50 text-gray-400 hover:text-white backdrop-blur-md border border-dendrite-base'
        } relative overflow-hidden`}
        animate={{
          scale: isActive ? 1.05 : 1,
          boxShadow: isActive ? '0 0 15px rgba(100, 200, 255, 0.5)' : 'none'
        }}
        transition={{
          type: "spring",
          stiffness: 500,
          damping: 20
        }}
      >
        {isActive && (
          <>
            <div className="absolute inset-0 bg-gradient-to-t from-neural-300/20 to-neural-400/5 opacity-50"></div>
            <motion.div
              className="absolute inset-0 bg-gradient-to-r from-neural-400/20 to-neural-500/20"
              animate={{
                opacity: [0.5, 0.8, 0.5],
              }}
              transition={{
                duration: 2,
                repeat: Infinity,
                repeatType: "reverse"
              }}
            />
          </>
        )}
        <Icon size={22} className="w-5 h-5 relative z-10" />
      </motion.div>
      <motion.span 
        className={`text-[10px] mt-1 ${isActive ? 'neural-text-gradient text-shadow-neural-glow font-medium' : 'text-gray-400'}`}
        animate={{
          opacity: isActive ? 1 : 0.7,
        }}
      >
        {label}
      </motion.span>
      
      {isActive && (
        <motion.div
          className="absolute -bottom-0.5 left-1/2 w-1 h-1 bg-neural-300 rounded-full"
          initial={{ opacity: 0 }}
          animate={{ 
            opacity: [0.5, 1, 0.5],
            boxShadow: [
              '0 0 3px rgba(100, 200, 255, 0.3)',
              '0 0 8px rgba(100, 200, 255, 0.7)',
              '0 0 3px rgba(100, 200, 255, 0.3)'
            ]
          }}
          transition={{ 
            duration: 2,
            repeat: Infinity,
            repeatType: "reverse"
          }}
          style={{ transform: 'translateX(-50%)' }}
        />
      )}
    </motion.div>
  );
});

DockIcon.displayName = 'DockIcon';

const DockBar = ({ activeTab, setActiveTab }) => {
  const navigate = useNavigate();
  const location = useLocation();
  
  const currentPath = location.pathname.substring(1) || 'dashboard';
  
  // Define dock items
  const dockItems = [
    { id: 'dashboard', icon: IconDashboard, label: 'Home', path: '/dashboard' },
    { id: 'tasks', icon: IconTasks, label: 'Tasks', path: '/tasks' },
    { id: 'pomodoro', icon: IconPomodoro, label: 'Focus', path: '/pomodoro' },
    { id: 'books', icon: IconBook, label: 'Books', path: '/books' },
    { id: 'profile', icon: IconProfile, label: 'Profile', path: '/profile' },
  ];
  
  // Update active tab based on current location
  React.useEffect(() => {
    setActiveTab(currentPath);
  }, [currentPath, setActiveTab]);
  
  // Simplified click handler that just updates active tab and navigates
  const handleIconClick = (path) => {
    const tabId = path.substring(1);
    setActiveTab(tabId);
    navigate(path);
  };

  return (
    <motion.nav 
      className="fixed bottom-0 left-0 right-0 bg-gray-900/80 backdrop-blur-xl border-t border-dendrite-base shadow-lg py-1 z-40"
      variants={dockVariants}
      initial="hidden"
      animate="visible"
      role="navigation"
      aria-label="Main navigation"
    >
      <div className="max-w-screen-xl mx-auto px-2 py-0.5 relative">
        {/* Neural connection lines */}
        <div className="absolute inset-y-0 left-0 right-0 overflow-hidden pointer-events-none">
          {dockItems.slice(0, -1).map((item, index) => (
            <NeuralConnector 
              key={`connector-${index}`}
              startX={(index + 0.5) * (100 / dockItems.length)}
              endX={(index + 1.5) * (100 / dockItems.length)}
              isActive={activeTab === item.id || activeTab === dockItems[index + 1].id}
            />
          ))}
        </div>
        
        <div className="flex items-center justify-around">
          {dockItems.map((item) => (
            <DockIcon
              key={item.id}
              icon={item.icon}
              label={item.label}
              isActive={activeTab === item.id}
              onClick={handleIconClick}
              to={item.path}
            />
          ))}
        </div>
      </div>
      
      {/* Safe area inset for iOS devices */}
      <div className="h-safe-area-inset-bottom bg-gray-900/80 backdrop-blur-xl"></div>
    </motion.nav>
  );
};

export default DockBar; 