import React, { useState, useEffect, lazy, Suspense } from 'react';
import { Routes, Route, Navigate } from 'react-router-dom';
import { AnimatePresence } from 'framer-motion';
import './App.css';

// Components
import DockBar from './components/DockBar';
// import AnimatedNotificationBar from './components/AnimatedNotificationBar';
import CircularProgressBar from './components/CircularProgressBar';
import ParallaxBackground from './components/ParallaxBackground';
import ErrorBoundary from './components/ErrorBoundary';

// Context Providers
import { NotificationProvider } from './components/NotificationContext';
import { ThemeProvider, ThemeToggle, ThemeTransition } from './contexts/ThemeContext';
import { NavigationProvider } from './contexts/NavigationContext';

// Demo Data
import { demoStudyData, demoTasks, demoBookPages } from './data/demoData';

// Lazy loaded pages/views for better performance
const Dashboard = lazy(() => import('./pages/Dashboard'));
const Tasks = lazy(() => import('./pages/Tasks'));
const Pomodoro = lazy(() => import('./pages/Pomodoro'));
const Books = lazy(() => import('./pages/Books'));
const Profile = lazy(() => import('./pages/Profile'));
const Calendar = lazy(() => import('./pages/Calendar'));
const Statistics = lazy(() => import('./pages/Statistics'));

// Loading component for Suspense fallback
const LoadingFallback = () => (
  <div className="flex items-center justify-center min-h-[50vh]">
    <CircularProgressBar 
      progress={100} 
      status="inProgress" 
      animationDuration={1.5}
    >
      <div className="neural-signal">
        <div className="w-10 h-10 bg-neuron-light rounded-full animate-neural-pulse"></div>
      </div>
    </CircularProgressBar>
  </div>
);

function App() {
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState('dashboard');

  useEffect(() => {
    // Ensure proper scrolling behavior
    document.body.style.overflow = 'auto';
    document.body.style.height = 'auto';
    document.documentElement.style.overflow = 'auto'; 
    document.documentElement.style.height = 'auto';
  }, []);

  useEffect(() => {
    // Simulate loading time - reduced for better UX
    const timer = setTimeout(() => {
      setLoading(false);
    }, 800);

    return () => clearTimeout(timer);
  }, []);

  // Application routes
  const appRoutes = (
    <Routes>
      <Route path="/" element={<Navigate to="/dashboard" replace />} />
      <Route path="/dashboard" element={<Dashboard studyData={demoStudyData} tasks={demoTasks} />} />
      <Route path="/tasks" element={<Tasks tasks={demoTasks} />} />
      <Route path="/pomodoro" element={<Pomodoro tasks={demoTasks} />} />
      <Route path="/books" element={<Books pages={demoBookPages} />} />
      <Route path="/calendar" element={<Calendar />} />
      <Route path="/statistics" element={<Statistics />} />
      <Route path="/profile" element={<Profile studyData={demoStudyData} tasks={demoTasks} />} />
      <Route path="*" element={<Navigate to="/dashboard" replace />} />
    </Routes>
  );

  return (
    <ThemeProvider>
      <ThemeTransition>
        <NotificationProvider>
          <NavigationProvider>
            <div className="App relative min-h-screen overflow-x-hidden">
              {/* Background Effects */}
              <ParallaxBackground />
              
              {/* Loading Screen */}
              {loading ? (
                <div className="loading absolute inset-0 flex items-center justify-center bg-neural-gradient z-50">
                  <div className="flex flex-col items-center">
                    <div className="relative">
                      <div className="neural-signal">
                        <div className="w-16 h-16 bg-neuron-light opacity-70 rounded-full animate-neural-pulse"></div>
                      </div>
                      
                      {/* Synaptic connections animation */}
                      <svg className="absolute top-0 left-0 w-full h-full -z-10" viewBox="0 0 100 100">
                        {Array.from({ length: 8 }).map((_, i) => (
                          <line 
                            key={`synapse-${i}`}
                            x1="50" 
                            y1="50" 
                            x2={50 + 40 * Math.cos(i * Math.PI / 4)} 
                            y2={50 + 40 * Math.sin(i * Math.PI / 4)}
                            stroke="rgba(100, 200, 255, 0.3)"
                            strokeWidth="0.5"
                            strokeDasharray="3,3"
                            className="animate-pulse"
                          />
                        ))}
                      </svg>
                    </div>
                    
                    <h1 className="text-2xl font-bold text-white mt-6 neural-text-gradient text-shadow-neural-glow">
                      Loading Neural Study Network
                    </h1>
                  </div>
                </div>
              ) : (
                <>
                  {/* Theme Toggle Button */}
                  <div className="fixed top-4 right-4 z-50">
                    <ThemeToggle className="neural-button bg-opacity-50 text-white p-2 rounded-full" />
                  </div>
                  
                  {/* Main Content Area */}
                  <main className="pt-4 pb-16 px-2 md:px-4 min-h-screen overflow-y-auto overflow-x-hidden" 
                        style={{height: "100vh", position: "relative", WebkitOverflowScrolling: "touch"}}>
                    <AnimatePresence mode="wait" initial={false}>
                      <Suspense fallback={<LoadingFallback />}>
                        <ErrorBoundary>
                          {appRoutes}
                        </ErrorBoundary>
                      </Suspense>
                    </AnimatePresence>
                  </main>
                  
                  {/* Dock Bar */}
                  <DockBar activeTab={activeTab} setActiveTab={setActiveTab} />
                </>
              )}
            </div>
          </NavigationProvider>
        </NotificationProvider>
      </ThemeTransition>
    </ThemeProvider>
  );
}

export default App;
